package sprint

import (
	"context"
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"errors"
	"fmt"
	"io/fs"
	"os"
	"os/exec"
	"path/filepath"
	"sort"
	"strings"
	"time"
)

type VerifyRequest struct {
	To       PlanningStage
	DryRun   bool
	Review   ReviewRequest
	Smoke    SmokeRequest
	Progress func(FlowProgress)
}

type VerifyResult struct {
	Project      string             `json:"project"`
	Sprint       string             `json:"sprint"`
	To           PlanningStage      `json:"to"`
	DryRun       bool               `json:"dry_run"`
	ReviewResult *ReviewResult      `json:"review_result,omitempty"`
	SmokeResult  *SmokeResult       `json:"smoke_result,omitempty"`
	Verification VerificationStatus `json:"verification"`
}

// Verify is the sole review-to-smoke transition. It requires complete execute
// evidence, reuses current canonical review evidence, and applies the smoke gate.
func (s Service) Verify(ctx context.Context, projectRef, sprintRef string, req VerifyRequest) (VerifyResult, error) {
	if !req.DryRun {
		lockedCtx, release, lockErr := s.acquireMutationContext(ctx, projectRef, sprintRef)
		if lockErr != nil {
			return VerifyResult{}, lockErr
		}
		defer release()
		ctx = lockedCtx
	}
	if req.To == "" {
		req.To = StageSmoke
	}
	if req.To != StageReview && req.To != StageSmoke {
		return VerifyResult{}, fmt.Errorf("verify target must be review or smoke")
	}
	result := VerifyResult{Project: projectRef, Sprint: sprintRef, To: req.To, DryRun: req.DryRun}
	if err := s.requireCompleteExecute(projectRef, sprintRef); err != nil {
		return result, err
	}
	status, statusErr := s.VerificationStatus(projectRef, sprintRef)
	if statusErr != nil && !errors.Is(statusErr, ErrFlowStateMissing) {
		return result, statusErr
	}
	if statusErr == nil {
		result.Verification = status
	}
	currentReview := statusErr == nil && status.Review.Fresh && status.Review.ExecutionStatus == string(ReviewCompleted) && !req.Review.Restart
	if !currentReview {
		if req.Progress != nil {
			req.Progress(FlowProgress{Stage: StageReview, State: "running", Message: "obtaining current review evidence"})
		}
		reviewReq := req.Review
		reviewReq.DryRun = req.DryRun
		review, err := s.Review(ctx, projectRef, sprintRef, reviewReq)
		result.ReviewResult = &review
		allowDiagnosticContinuation := req.To == StageSmoke && review.Status == ReviewCompleted && review.Verdict == ReviewFail && req.Smoke.ForceReview && req.Smoke.OverrideConfirmed && strings.TrimSpace(req.Smoke.OverrideRationale) != ""
		if err != nil && !allowDiagnosticContinuation {
			return result, err
		}
	} else if req.Progress != nil {
		req.Progress(FlowProgress{Stage: StageReview, State: "skipped", Message: "current review evidence is acceptable"})
	}
	if req.To == StageReview || req.DryRun {
		if !req.DryRun {
			result.Verification, _ = s.VerificationStatus(projectRef, sprintRef)
		}
		return result, nil
	}
	if req.Progress != nil {
		req.Progress(FlowProgress{Stage: StageSmoke, State: "running", Message: "evaluating review gate and running smoke"})
	}
	smokeReq := req.Smoke
	smoke, err := s.RunSmoke(ctx, projectRef, sprintRef, smokeReq)
	result.SmokeResult = &smoke
	result.Verification, _ = s.VerificationStatus(projectRef, sprintRef)
	return result, err
}

func (s Service) requireCompleteExecute(projectRef, sprintRef string) error {
	sp, _, _, err := s.resolveSprintInputs(projectRef, sprintRef)
	if err != nil {
		return err
	}
	state, err := LoadExecuteRunState(s.root, sp)
	if err != nil {
		path, pathErr := ExecuteRunStatePath(s.root, sp)
		if pathErr == nil {
			var summary struct {
				Status string   `json:"status"`
				Files  []string `json:"files"`
			}
			if data, readErr := os.ReadFile(path); readErr == nil && json.Unmarshal(data, &summary) == nil && (summary.Status == "complete" || summary.Status == "completed") && len(summary.Files) > 0 {
				content, artifactErr := s.store.ReadArtifact(sp, StageExecute)
				if artifactErr == nil && strings.TrimSpace(content) != "" {
					return nil
				}
			}
		}
		return fmt.Errorf("execute evidence is incomplete: %w", err)
	}
	if len(state.Tasks) == 0 {
		return fmt.Errorf("execute evidence is incomplete: no planned tasks")
	}
	for _, task := range state.Tasks {
		if task.Status != ExecuteTaskComplete && task.Status != ExecuteTaskDeferred {
			return fmt.Errorf("execute evidence is incomplete: task %q is %s", task.Identity.Name, task.Status)
		}
	}
	data, err := s.store.ReadArtifact(sp, StageExecute)
	if err != nil || strings.TrimSpace(data) == "" {
		return fmt.Errorf("execute evidence is incomplete: execute.md is missing")
	}
	return nil
}

func (s Service) ExecuteComplete(projectRef, sprintRef string) (bool, error) {
	err := s.requireCompleteExecute(projectRef, sprintRef)
	if err != nil {
		return false, nil
	}
	return true, nil
}

func (s Service) VerificationStatus(projectRef, sprintRef string) (VerificationStatus, error) {
	sp, _, _, err := s.resolveSprintInputs(projectRef, sprintRef)
	if err != nil {
		return VerificationStatus{}, err
	}
	out := VerificationStatus{Project: sp.Project, Sprint: sp.Slug}
	out.Review = VerificationStage{Stage: StageReview, ExecutionStatus: "missing", Artifact: ArtifactRelPath(sp, StageReview), NextAction: "Run review."}
	out.Smoke = VerificationStage{Stage: StageSmoke, ExecutionStatus: "missing", Artifact: ArtifactRelPath(sp, StageSmoke), NextAction: "Run smoke after a current acceptable review."}
	state, err := LoadFlowState(s.root, sp)
	if err != nil {
		return out, err
	}
	// Status derives expired-attempt truth without mutating durable state.
	// The next explicit review/smoke operation owns any persisted transition.
	reconcileExpiredAttempts(&state, s.now().UTC())
	malformed := false
	if state.Review != nil {
		r := state.Review
		out.Review.ExecutionStatus, out.Review.Verdict = string(r.Status), string(r.Verdict)
		out.Review.InputFingerprint, out.Review.ArtifactDigest = r.Fingerprint, r.ArtifactDigest
		out.Review.ActiveAttempt, out.Review.LastAttempt = r.ActiveAttempt, r.LastAttempt
		if r.Resume != nil {
			out.Review.Total = len(r.Resume.Coverage)
			for _, checkpoint := range r.Resume.Coverage {
				if checkpoint.Status == AttemptCompleted {
					out.Review.Completed++
				}
				if checkpoint.SessionID != "" && checkpoint.Status != AttemptCompleted {
					out.Review.RetainedSessions++
				}
			}
			out.Review.Resumable = out.Review.Completed > 0
		}
		manifest, findings, prepareErr := s.PrepareReview(projectRef, sprintRef, ReviewRequest{})
		if prepareErr != nil || len(findings) > 0 {
			out.Review.FreshnessReasons = append(out.Review.FreshnessReasons, "governed review inputs are unavailable or invalid")
		} else if strictCompletedReviewSnapshotFreshness && manifest.Fingerprint != r.Fingerprint {
			out.Review.FreshnessReasons = append(out.Review.FreshnessReasons, "review input fingerprint changed")
		}
		if r.Resume != nil && (prepareErr != nil || len(findings) > 0 || manifest.Fingerprint != r.Resume.InputFingerprint || manifest.Model != r.Resume.Model) {
			out.Review.Resumable = false
		}
		data, readErr := os.ReadFile(mustArtifactPath(s.root, sp, StageReview))
		if readErr != nil {
			out.Review.FreshnessReasons = append(out.Review.FreshnessReasons, "review artifact is missing")
		} else {
			if r.ArtifactDigest == "" || hashBytes(data) != r.ArtifactDigest {
				out.Review.FreshnessReasons = append(out.Review.FreshnessReasons, "review artifact digest changed")
			}
			validationManifest := manifest
			if !strictCompletedReviewSnapshotFreshness {
				// Validate the canonical artifact against the fingerprint recorded when
				// it completed, rather than a later filesystem snapshot.
				validationManifest.Fingerprint = r.Fingerprint
			}
			if prepareErr == nil && len(findings) == 0 && len(ValidateReviewContent(string(data), validationManifest)) > 0 {
				malformed = true
				out.Review.FreshnessReasons = append(out.Review.FreshnessReasons, "review artifact is malformed")
			}
		}
		out.Review.Fresh = len(out.Review.FreshnessReasons) == 0 && r.LastComplete != nil
		if !out.Review.Fresh {
			if out.Review.Resumable {
				out.Review.NextAction = fmt.Sprintf("Resume review from %d/%d validated coverage (%d retained sessions), or restart it explicitly.", out.Review.Completed, out.Review.Total, out.Review.RetainedSessions)
			} else {
				out.Review.NextAction = "Rerun review using the current governed inputs."
			}
		} else {
			out.Review.NextAction = "Review is current."
		}
	}
	if state.Smoke != nil {
		sm := state.Smoke
		out.Smoke.ExecutionStatus, out.Smoke.Verdict = string(sm.Status), string(sm.Verdict)
		out.Smoke.InputFingerprint, out.Smoke.ArtifactDigest, out.Smoke.RunID = sm.InputFingerprint, sm.ArtifactDigest, sm.RunID
		out.Smoke.Issues, out.Smoke.Evidence, out.Smoke.Override = append([]SmokeIssue(nil), sm.Issues...), append([]EvidenceReference(nil), sm.Evidence...), sm.Override
		out.Smoke.ActiveAttempt, out.Smoke.LastAttempt = sm.ActiveAttempt, sm.LastAttempt
		if !out.Review.Fresh {
			out.Smoke.FreshnessReasons = append(out.Smoke.FreshnessReasons, "review evidence is not current")
		}
		data, readErr := os.ReadFile(mustArtifactPath(s.root, sp, StageSmoke))
		if readErr != nil {
			out.Smoke.FreshnessReasons = append(out.Smoke.FreshnessReasons, "smoke artifact is missing")
		} else {
			if sm.ArtifactDigest == "" || hashBytes(data) != sm.ArtifactDigest {
				out.Smoke.FreshnessReasons = append(out.Smoke.FreshnessReasons, "smoke artifact digest changed")
			}
			if len(ValidateSmokeContent(string(data))) > 0 {
				malformed = true
				out.Smoke.FreshnessReasons = append(out.Smoke.FreshnessReasons, "smoke artifact is malformed")
			}
		}
		if sm.LastComplete == nil || sm.InputFingerprint == "" {
			out.Smoke.FreshnessReasons = append(out.Smoke.FreshnessReasons, "smoke input fingerprint is unavailable")
		} else if strictCompletedSmokeSnapshotFreshness {
			if fingerprint, identityErr := refreshEvidenceFingerprint(sm.LastComplete.Evidence); identityErr != nil || fingerprint != sm.InputFingerprint {
				out.Smoke.FreshnessReasons = append(out.Smoke.FreshnessReasons, "smoke inputs or external evidence changed")
			}
		}
		out.Smoke.Fresh = len(out.Smoke.FreshnessReasons) == 0
		if !out.Smoke.Fresh {
			out.Smoke.NextAction = "Rerun the required containing smoke suite."
		} else {
			out.Smoke.NextAction = "Smoke evidence is current."
		}
	}
	out.Assessment, out.NextAction = deriveAssessment(out.Review, out.Smoke, malformed)
	return out, nil
}

func deriveAssessment(review, smoke VerificationStage, malformed bool) (OverallAssessment, string) {
	if malformed {
		return AssessmentBlocked, "Repair or regenerate malformed canonical verification evidence."
	}
	if review.Fresh && review.Verdict == string(ReviewFail) {
		return AssessmentFail, "Resolve review findings and rerun review; diagnostic smoke cannot change this result."
	}
	if review.Fresh && review.Verdict == string(ReviewVerdictBlocked) {
		return AssessmentBlocked, "Satisfy the review prerequisite and rerun review."
	}
	if !review.Fresh || review.ExecutionStatus != string(ReviewCompleted) || !smoke.Fresh || smoke.ExecutionStatus != string(SmokeCompleted) {
		if !review.Fresh || review.ExecutionStatus != string(ReviewCompleted) {
			return AssessmentIncomplete, "Run or retry review, the earliest non-current verification stage."
		}
		return AssessmentIncomplete, "Run or retry smoke, the earliest non-current verification stage."
	}
	switch SmokeVerdict(smoke.Verdict) {
	case SmokeFailVerdict:
		return AssessmentFail, "Resolve the classified failure and rerun the required containing suite."
	case SmokeBlockedVerdict:
		return AssessmentBlocked, "Restore smoke prerequisites, coverage, or evidence and rerun smoke."
	case SmokeNotApplicable:
		return AssessmentNotApplicable, "No runtime smoke is applicable; retain the current review rationale."
	case SmokePassWithOpenIssues:
		return AssessmentPassWithFindings, "Resolve linked relevant issues and rerun narrow plus containing scope."
	case SmokePass:
		if ReviewVerdict(review.Verdict) == ReviewPassWithFindings {
			return AssessmentPassWithFindings, "Address review findings if a clean assessment is required."
		}
		return AssessmentPass, "No verification action required."
	default:
		return AssessmentBlocked, "Repair the unsupported smoke verdict."
	}
}

func smokeInputFingerprint(p smokePrepared, result SmokeResult) string {
	refs := smokeIdentityReferences(p, result)
	fingerprint, _ := refreshEvidenceFingerprint(refs)
	return fingerprint
}

func smokeIdentityReferences(p smokePrepared, result SmokeResult) []EvidenceReference {
	refs := []EvidenceReference{
		{Kind: "file", Path: p.ManifestPath},
		{Kind: "file", Path: filepath.Join(p.Sprint.Path, "review.md")},
		{Kind: "fact", Path: "review-fingerprint", Digest: result.ReviewFingerprint},
		{Kind: "fact", Path: "review-verdict", Digest: string(result.ReviewVerdict)},
		{Kind: "fact", Path: "scope", Digest: result.ScopeKind + ":" + result.Scope},
		{Kind: "fact", Path: "harness", Digest: result.Harness + ":" + result.Protocol},
		{Kind: "fact", Path: "prerequisites", Digest: strings.Join(result.Prerequisites, "\x00")},
		{Kind: "fact", Path: "timeout", Digest: result.EffectiveTimeout.String() + ":" + result.TimeoutSource},
	}
	if strictCompletedSmokeSnapshotFreshness {
		refs = append(refs, EvidenceReference{Kind: "target", Path: p.Target})
	}
	for _, evidence := range result.Evidence {
		path := evidence.Path
		if !filepath.IsAbs(path) {
			path = filepath.Join(p.HarnessRoot, filepath.FromSlash(path))
		}
		refs = append(refs, EvidenceReference{Kind: "file", Path: path})
	}
	for _, issue := range result.Issues {
		path := issue.Path
		if !filepath.IsAbs(path) {
			path = filepath.Join(p.HarnessRoot, filepath.FromSlash(path))
		}
		refs = append(refs, EvidenceReference{Kind: "file", Path: path}, EvidenceReference{Kind: "fact", Path: "issue:" + issue.ID, Digest: issue.Status})
	}
	sort.Slice(refs, func(i, j int) bool {
		if refs[i].Path == refs[j].Path {
			return refs[i].Kind < refs[j].Kind
		}
		return refs[i].Path < refs[j].Path
	})
	return refs
}

func refreshEvidenceFingerprint(refs []EvidenceReference) (string, error) {
	h := sha256.New()
	for _, ref := range refs {
		digest := ref.Digest
		var err error
		switch ref.Kind {
		case "file":
			digest, err = hashFile(ref.Path)
		case "target":
			digest, err = targetIdentity(ref.Path)
		}
		if err != nil {
			return "", err
		}
		fmt.Fprintf(h, "%s\x00%s\x00%s\n", ref.Kind, filepath.ToSlash(ref.Path), digest)
	}
	return hex.EncodeToString(h.Sum(nil)), nil
}

func targetIdentity(root string) (string, error) {
	root, err := filepath.Abs(root)
	if err != nil {
		return "", err
	}
	rootInfo, err := os.Lstat(root)
	if err != nil {
		return "", err
	}
	if rootInfo.Mode()&os.ModeSymlink != 0 {
		return "", fmt.Errorf("target root must not be a symlink")
	}
	paths := []string{}
	head := "non-git"
	gitRootOK := false
	if output, gitErr := exec.Command("git", "-C", root, "rev-parse", "--show-toplevel").Output(); gitErr == nil {
		gitRoot, absErr := filepath.Abs(strings.TrimSpace(string(output)))
		gitRootOK = absErr == nil && filepath.Clean(gitRoot) == filepath.Clean(root)
	}
	if output, gitErr := exec.Command("git", "-C", root, "rev-parse", "HEAD").Output(); gitErr == nil && gitRootOK {
		head = strings.TrimSpace(string(output))
		if output, listErr := exec.Command("git", "-C", root, "ls-files", "-co", "--exclude-standard", "-z").Output(); listErr == nil {
			for _, value := range strings.Split(string(output), "\x00") {
				if value != "" {
					paths = append(paths, filepath.ToSlash(filepath.Clean(value)))
				}
			}
		}
	}
	if len(paths) == 0 {
		err = filepath.WalkDir(root, func(path string, entry fs.DirEntry, walkErr error) error {
			if walkErr != nil {
				return walkErr
			}
			rel, relErr := filepath.Rel(root, path)
			if relErr != nil {
				return relErr
			}
			if entry.IsDir() && entry.Name() == ".git" {
				return filepath.SkipDir
			}
			if rel == "." || entry.IsDir() {
				return nil
			}
			paths = append(paths, filepath.ToSlash(rel))
			return nil
		})
		if err != nil {
			return "", err
		}
	}
	sort.Strings(paths)
	h := sha256.New()
	fmt.Fprintf(h, "root=%s\nhead=%s\n", filepath.ToSlash(root), head)
	for _, rel := range paths {
		full := filepath.Join(root, filepath.FromSlash(rel))
		info, statErr := os.Lstat(full)
		if errors.Is(statErr, os.ErrNotExist) {
			fmt.Fprintf(h, "%s\x00missing\n", rel)
			continue
		}
		if statErr != nil {
			return "", statErr
		}
		if info.Mode()&os.ModeSymlink != 0 {
			linkValue, linkErr := os.Readlink(full)
			if linkErr != nil {
				return "", linkErr
			}
			target, linkErr := filepath.EvalSymlinks(full)
			if linkErr != nil || !inside(root, target) {
				return "", fmt.Errorf("target symlink escapes or is unreadable: %s", rel)
			}
			fmt.Fprintf(h, "%s\x00symlink=%s\n", rel, filepath.ToSlash(linkValue))
			info, statErr = os.Stat(target)
			if statErr != nil {
				return "", statErr
			}
			full = target
		}
		if !info.Mode().IsRegular() {
			fmt.Fprintf(h, "%s\x00non-regular\n", rel)
			continue
		}
		if info.Size() > 64<<20 {
			return "", fmt.Errorf("target file exceeds bounded identity read: %s", rel)
		}
		digest, readErr := hashFile(full)
		if readErr != nil {
			return "", readErr
		}
		fmt.Fprintf(h, "%s\x00%s\n", rel, digest)
	}
	return hex.EncodeToString(h.Sum(nil)), nil
}

// targetRevisionIdentity deliberately excludes unrelated dirty files. Review
// separately freezes every execute-reported changed path, so repository-wide
// hashing would make an unrelated edit invalidate an otherwise atomic review.
func targetRevisionIdentity(root string) (string, error) {
	root, err := filepath.Abs(root)
	if err != nil {
		return "", err
	}
	head := "non-git"
	if output, gitErr := exec.Command("git", "-C", root, "rev-parse", "--show-toplevel").Output(); gitErr == nil {
		gitRoot, absErr := filepath.Abs(strings.TrimSpace(string(output)))
		if absErr == nil && filepath.Clean(gitRoot) == filepath.Clean(root) {
			if output, headErr := exec.Command("git", "-C", root, "rev-parse", "HEAD").Output(); headErr == nil {
				head = strings.TrimSpace(string(output))
			}
		}
	}
	h := sha256.New()
	fmt.Fprintf(h, "root=%s\nhead=%s\n", filepath.ToSlash(root), head)
	return hex.EncodeToString(h.Sum(nil)), nil
}

func attemptExpired(attempt *VerificationAttempt, now time.Time) bool {
	if attempt == nil || attempt.Status != AttemptRunning {
		return false
	}
	if attempt.OwnerPID > 0 && !verificationProcessAlive(attempt.OwnerPID) {
		return true
	}
	lastSeen := attempt.StartedAt
	if attempt.HeartbeatAt.After(lastSeen) {
		lastSeen = attempt.HeartbeatAt
	}
	return now.Sub(lastSeen) > 2*time.Hour
}

func reconcileExpiredAttempts(state *FlowState, now time.Time) bool {
	changed := false
	if state.Review != nil && attemptExpired(state.Review.ActiveAttempt, now) {
		attempt := *state.Review.ActiveAttempt
		attempt.Status = AttemptTimedOut
		attempt.CompletedAt = &now
		attempt.Category = "interrupted"
		attempt.Diagnostics = []string{"review attempt expired without a terminal update"}
		attempt.NextAction = "Resume the retained review coverage, or restart review explicitly."
		state.Review.ActiveAttempt = nil
		state.Review.LastAttempt = &attempt
		state.Review.Status = ReviewFailed
		state.Review.LastRunAt = &now
		changed = true
	}
	if state.Smoke != nil && attemptExpired(state.Smoke.ActiveAttempt, now) {
		attempt := *state.Smoke.ActiveAttempt
		attempt.Status = AttemptTimedOut
		attempt.CompletedAt = &now
		attempt.Category = "interrupted"
		attempt.Diagnostics = []string{"smoke attempt expired without a terminal update"}
		attempt.NextAction = "Confirm no harness process remains, then rerun smoke."
		state.Smoke.ActiveAttempt = nil
		state.Smoke.LastAttempt = &attempt
		state.Smoke.Status = SmokeFailed
		state.Smoke.LastRunAt = &now
		changed = true
	}
	return changed
}

package sprint

import (
	"context"
	"fmt"
	"strings"
	"time"

	"github.com/Antonio7098/ultraplan-go/internal/platform/config"
	"github.com/Antonio7098/ultraplan-go/internal/platform/gitpublish"
	"github.com/Antonio7098/ultraplan-go/internal/platform/runtime"
)

type Runtime interface {
	StartRun(context.Context, runtime.Request) (runtime.Result, error)
}

type sessionDeleter interface {
	DeleteSession(context.Context, string) error
}

type runtimeStoreDeleter interface {
	DeleteRuntimeStore(context.Context, string) error
}

func (s Service) deleteCompletedSession(ctx context.Context, sessionID string) error {
	if strings.TrimSpace(sessionID) == "" {
		return nil
	}
	deleter, ok := s.runtime.(sessionDeleter)
	if !ok {
		return nil
	}
	return deleter.DeleteSession(ctx, sessionID)
}

func (s Service) deleteCompletedSessions(ctx context.Context, result runtime.Result) error {
	if result.RuntimeStorePath != "" {
		if deleter, ok := s.runtime.(runtimeStoreDeleter); ok {
			return deleter.DeleteRuntimeStore(ctx, result.RuntimeStorePath)
		}
	}
	ids := append([]string(nil), result.SessionIDs...)
	ids = append(ids, result.SessionID)
	seen := map[string]bool{}
	for _, id := range ids {
		if strings.TrimSpace(id) == "" || seen[id] {
			continue
		}
		seen[id] = true
		if err := s.deleteCompletedSession(ctx, id); err != nil {
			return err
		}
	}
	return nil
}

type FlowRequest struct {
	To              PlanningStage
	DryRun          bool
	ModelOverride   string
	VariantOverride string
	// StageOverrides optionally sets a per-stage runtime model and/or variant
	// for this flow invocation. Stages without an entry keep their configured
	// defaults unchanged.
	StageOverrides map[PlanningStage]StageRuntime
	Review         ReviewRequest
	Smoke          SmokeRequest
	Progress       func(FlowProgress)
}

type FlowProgress struct {
	Stage   PlanningStage
	State   string
	Message string
}

type FlowResult struct {
	Project      string
	Sprint       string
	To           PlanningStage
	DryRun       bool
	Message      string
	Runtime      runtime.Result
	Stages       []StageState
	Findings     []ValidationFinding
	Publications []gitpublish.Result
}

// Flow owns the ordered sprint state machine. Surfaces map requests and render
// this result; they do not schedule stages or duplicate verification policy.
func (s Service) Flow(ctx context.Context, projectRef, sprintRef string, req FlowRequest) (FlowResult, error) {
	stages, err := flowStages(req.To)
	if err != nil {
		return FlowResult{}, err
	}
	if req.DryRun {
		if req.To == StageReview || req.To == StageSmoke {
			verified, verifyErr := s.Verify(ctx, projectRef, sprintRef, VerifyRequest{To: req.To, DryRun: true, Review: req.Review, Smoke: req.Smoke, Progress: req.Progress})
			message := "verification dry run"
			if verified.ReviewResult != nil {
				message = firstNonEmptyString(verified.ReviewResult.Prompt, verified.ReviewResult.Message, message)
			}
			return FlowResult{Project: verified.Project, Sprint: verified.Sprint, To: req.To, DryRun: true, Message: message}, verifyErr
		}
		stages = []PlanningStage{req.To}
	} else {
		// A non-dry flow is the materialization entrypoint for a roadmap sprint.
		// Create its safe skeleton before acquiring the sprint-scoped mutation
		// lease; lease resolution deliberately accepts existing sprints only.
		sp, _, _, resolveErr := s.resolveSprintForRequirements(projectRef, sprintRef, true)
		if resolveErr != nil {
			return FlowResult{}, resolveErr
		}
		sprintRef = sp.Slug
		var release func()
		ctx, release, err = s.acquireMutationContext(ctx, projectRef, sprintRef)
		if err != nil {
			return FlowResult{}, err
		}
		defer release()
	}
	var result FlowResult
	for _, stage := range stages {
		emitFlow(req.Progress, FlowProgress{Stage: stage, State: "checking", Message: "checking prerequisites and existing artifact"})
		stageReq := FlowRequest{To: stage, DryRun: req.DryRun, ModelOverride: req.ModelOverride, VariantOverride: req.VariantOverride}
		if !req.DryRun {
			valid, validateErr := s.flowStageAlreadyValid(projectRef, sprintRef, stage)
			if validateErr != nil {
				return FlowResult{}, validateErr
			}
			if valid {
				if stage == StageCodeContext {
					sp, inputs, _, resolveErr := s.resolveSprintInputs(projectRef, sprintRef)
					if resolveErr != nil {
						return FlowResult{}, resolveErr
					}
					if _, findings := s.resolveSprintTarget(sp, inputs.ProjectIndex, true); len(findings) > 0 {
						return FlowResult{Project: sp.Project, Sprint: sp.Slug, To: stage, Findings: findings}, fmt.Errorf("code-context sprint workspace creation failed")
					}
				}
				if stage != StageExecute {
					if sp, _, _, resolveErr := s.resolveSprintInputs(projectRef, sprintRef); resolveErr == nil {
						_ = clearPlanningStageSession(sp, stage)
					}
				}
				result = FlowResult{Project: projectRef, Sprint: sprintRef, To: stage, Message: string(stage) + " already complete"}
				if stage != StageExecute {
					publications, publishErr := s.publishPlanningStage(ctx, projectRef, sprintRef, stage)
					result.Publications = append(result.Publications, publications...)
					if publishErr != nil {
						emitFlow(req.Progress, FlowProgress{Stage: stage, State: "publish-failed", Message: publishErr.Error()})
						return result, publishErr
					}
				}
				emitFlow(req.Progress, FlowProgress{Stage: stage, State: "skipped", Message: "already complete"})
				continue
			}
			emitFlow(req.Progress, FlowProgress{Stage: stage, State: "running", Message: "starting runtime-backed stage"})
		}
		var stageErr error
		result, stageErr = s.withStageOverrides(req.StageOverrides).runFlowStage(ctx, projectRef, sprintRef, stageReq)
		if stageErr != nil {
			emitFlow(req.Progress, FlowProgress{Stage: stage, State: "failed", Message: "stage failed; inspect validation findings and durable state"})
			return result, stageErr
		}
		if !req.DryRun && stage != StageExecute {
			emitFlow(req.Progress, FlowProgress{Stage: stage, State: "publishing", Message: "committing completed stage changes"})
			publications, publishErr := s.publishPlanningStage(ctx, projectRef, sprintRef, stage)
			result.Publications = append(result.Publications, publications...)
			if publishErr != nil {
				emitFlow(req.Progress, FlowProgress{Stage: stage, State: "publish-failed", Message: publishErr.Error()})
				return result, publishErr
			}
		}
		emitFlow(req.Progress, FlowProgress{Stage: stage, State: "complete", Message: firstNonEmptyString(result.Message, "stage complete")})
	}
	if req.To == StageReview || req.To == StageSmoke {
		verified, verifyErr := s.Verify(ctx, projectRef, sprintRef, VerifyRequest{To: req.To, Review: req.Review, Smoke: req.Smoke, Progress: req.Progress})
		message := fmt.Sprintf("verification assessment=%s next=%s", verified.Verification.Assessment, verified.Verification.NextAction)
		return FlowResult{Project: verified.Project, Sprint: verified.Sprint, To: req.To, Message: message}, verifyErr
	}
	result.To = req.To
	return result, nil
}

// FlowStage runs exactly one planning stage. It preserves the stage's normal
// prerequisite validation while deliberately not scheduling earlier stages.
func (s Service) FlowStage(ctx context.Context, projectRef, sprintRef string, req FlowRequest) (FlowResult, error) {
	if err := validatePlanningStageTarget(req.To); err != nil {
		return FlowResult{}, err
	}
	if !req.DryRun {
		sp, _, _, resolveErr := s.resolveSprintForRequirements(projectRef, sprintRef, true)
		if resolveErr != nil {
			return FlowResult{}, resolveErr
		}
		sprintRef = sp.Slug
		var release func()
		var err error
		ctx, release, err = s.acquireMutationContext(ctx, projectRef, sprintRef)
		if err != nil {
			return FlowResult{}, err
		}
		defer release()
	}
	emitFlow(req.Progress, FlowProgress{Stage: req.To, State: "running", Message: "running selected stage only"})
	result, err := s.withStageOverrides(req.StageOverrides).runFlowStage(ctx, projectRef, sprintRef, req)
	if err != nil {
		emitFlow(req.Progress, FlowProgress{Stage: req.To, State: "failed", Message: "stage failed; inspect validation findings and durable state"})
		return result, err
	}
	if !req.DryRun {
		emitFlow(req.Progress, FlowProgress{Stage: req.To, State: "publishing", Message: "committing completed stage changes"})
		publications, publishErr := s.publishPlanningStage(ctx, projectRef, sprintRef, req.To)
		result.Publications = append(result.Publications, publications...)
		if publishErr != nil {
			emitFlow(req.Progress, FlowProgress{Stage: req.To, State: "publish-failed", Message: publishErr.Error()})
			return result, publishErr
		}
	}
	emitFlow(req.Progress, FlowProgress{Stage: req.To, State: "complete", Message: firstNonEmptyString(result.Message, "stage complete")})
	return result, nil
}

func (s Service) runFlowStage(ctx context.Context, projectRef, sprintRef string, req FlowRequest) (FlowResult, error) {
	switch req.To {
	case StageRequirements:
		return s.FlowRequirements(ctx, projectRef, sprintRef, req)
	case StageCodeContext:
		return s.FlowCodeContext(ctx, projectRef, sprintRef, req)
	case StageSprintIndex:
		return s.FlowSprintIndex(ctx, projectRef, sprintRef, req)
	case StageTechnicalHandbook:
		return s.FlowTechnicalHandbook(ctx, projectRef, sprintRef, req)
	case StageAreaReasoning, StageReasoning:
		return s.FlowReasoning(ctx, projectRef, sprintRef, req)
	case StagePlan:
		return s.FlowPlan(ctx, projectRef, sprintRef, req)
	case StageExecute:
		execute, err := s.Execute(ctx, projectRef, sprintRef, ExecuteRequest{DryRun: req.DryRun, Resume: true})
		return FlowResult{Project: execute.Project, Sprint: execute.Sprint, To: StageExecute, DryRun: execute.DryRun, Message: firstNonEmptyString(execute.Prompt, execute.Message), Findings: execute.Findings}, err
	default:
		return FlowResult{}, fmt.Errorf("unsupported flow stage %q", req.To)
	}
}

func validatePlanningStageTarget(stage PlanningStage) error {
	switch stage {
	case StageRequirements, StageCodeContext, StageSprintIndex, StageTechnicalHandbook, StageAreaReasoning, StageReasoning, StagePlan:
		return nil
	default:
		return fmt.Errorf("unsupported single planning stage %q", stage)
	}
}

func flowStages(target PlanningStage) ([]PlanningStage, error) {
	if err := validateFlowTarget(target); err != nil {
		return nil, err
	}
	ordered := append(PlanningStages(), StageExecute)
	end := 0
	switch target {
	case StageRequirements:
		end = 1
	case StageCodeContext:
		end = 2
	case StageSprintIndex:
		end = 3
	case StageTechnicalHandbook:
		end = 4
	case StageAreaReasoning:
		end = 5
	case StageReasoning:
		end = 6
	case StagePlan:
		end = 7
	case StageExecute, StageReview, StageSmoke:
		end = 8
	}
	return append([]PlanningStage(nil), ordered[:end]...), nil
}

func (s Service) flowStageAlreadyValid(projectRef, sprintRef string, stage PlanningStage) (bool, error) {
	var result ValidationResult
	var err error
	switch stage {
	case StageRequirements:
		result, err = s.ValidateRequirements(projectRef, sprintRef)
	case StageCodeContext:
		sp, _, _, resolveErr := s.resolveSprintInputs(projectRef, sprintRef)
		if resolveErr != nil {
			return false, resolveErr
		}
		_, prerequisiteErr := s.codeContextPrerequisite(sp)
		return prerequisiteErr == nil, nil
	case StageSprintIndex:
		result, err = s.ValidateSprintIndex(projectRef, sprintRef)
	case StageTechnicalHandbook:
		result, err = s.ValidateTechnicalHandbook(projectRef, sprintRef)
	case StageAreaReasoning:
		result, err = s.ValidateAreaReasoning(projectRef, sprintRef)
	case StageReasoning:
		result, err = s.ValidateReasoning(projectRef, sprintRef)
	case StagePlan:
		result, err = s.ValidatePlan(projectRef, sprintRef)
	case StageExecute:
		return s.ExecuteComplete(projectRef, sprintRef)
	default:
		return false, fmt.Errorf("unsupported flow stage %q", stage)
	}
	if err != nil {
		return false, nil
	}
	return result.Valid(), nil
}

func emitFlow(progress func(FlowProgress), event FlowProgress) {
	if progress != nil {
		progress(event)
	}
}

func flowRequirementsSuccessStages(sp Sprint, now time.Time) []StageState {
	stages := emptyPlanningStageStates(sp)
	setFlowStage(stages, StageRequirements, StatusComplete, &now, "")
	setFlowStage(stages, StageCodeContext, StatusReady, nil, "")
	return stages
}

func flowCodeContextSuccessStages(sp Sprint, now time.Time) []StageState {
	stages := flowRequirementsSuccessStages(sp, now)
	setFlowStage(stages, StageCodeContext, StatusComplete, &now, "")
	setFlowStage(stages, StageSprintIndex, StatusReady, nil, "")
	return stages
}

func flowSprintIndexSuccessStages(sp Sprint, noTemplates bool, now time.Time) []StageState {
	stages := flowCodeContextSuccessStages(sp, now)
	setFlowStage(stages, StageSprintIndex, StatusComplete, &now, "")
	setFlowStage(stages, StageTechnicalHandbook, StatusReady, nil, "")
	if noTemplates {
		setFlowStage(stages, StageAreaReasoning, StatusSkipped, nil, "")
		setFlowStage(stages, StageReasoning, StatusReady, nil, "")
	}
	return stages
}

func flowTechnicalHandbookSuccessStages(sp Sprint, noTemplates bool, now time.Time) []StageState {
	stages := flowSprintIndexSuccessStages(sp, false, now)
	setFlowStage(stages, StageTechnicalHandbook, StatusComplete, &now, "")
	setFlowStage(stages, StageAreaReasoning, StatusReady, nil, "")
	if noTemplates {
		setFlowStage(stages, StageAreaReasoning, StatusSkipped, nil, "")
		setFlowStage(stages, StageReasoning, StatusReady, nil, "")
	}
	return stages
}

func flowAreaReasoningSuccessStages(sp Sprint, noTemplates bool, now time.Time) []StageState {
	stages := flowTechnicalHandbookSuccessStages(sp, noTemplates, now)
	if noTemplates {
		setFlowStage(stages, StageAreaReasoning, StatusSkipped, &now, "")
		setFlowStage(stages, StageReasoning, StatusReady, nil, "")
		return stages
	}
	setFlowStage(stages, StageAreaReasoning, StatusComplete, &now, "")
	setFlowStage(stages, StageReasoning, StatusReady, nil, "")
	return stages
}

func flowReasoningSuccessStages(sp Sprint, noTemplates bool, now time.Time) []StageState {
	stages := flowAreaReasoningSuccessStages(sp, noTemplates, now)
	setFlowStage(stages, StageReasoning, StatusComplete, &now, "")
	setFlowStage(stages, StagePlan, StatusReady, nil, "")
	return stages
}

func flowPlanSuccessStages(sp Sprint, noTemplates bool, now time.Time) []StageState {
	stages := flowReasoningSuccessStages(sp, noTemplates, now)
	setFlowStage(stages, StagePlan, StatusComplete, &now, "")
	return stages
}

func flowFailedStages(sp Sprint, target PlanningStage, err error, now time.Time) []StageState {
	msg := safeError(err)
	stages := emptyPlanningStageStates(sp)
	for _, stage := range PlanningStages() {
		if stage == target {
			setFlowStage(stages, stage, StatusFailed, &now, msg)
			break
		}
		setFlowStage(stages, stage, StatusComplete, nil, "")
	}
	return stages
}

func emptyPlanningStageStates(sp Sprint) []StageState {
	stages := make([]StageState, 0, len(PlanningStages()))
	for _, stage := range PlanningStages() {
		stages = append(stages, StageState{Stage: stage, Status: StatusMissing, Path: ArtifactRelPath(sp, stage)})
	}
	return stages
}

func setFlowStage(stages []StageState, target PlanningStage, status StageStatus, at *time.Time, detail string) {
	for i := range stages {
		if stages[i].Stage == target {
			stages[i].Status, stages[i].LastRunAt, stages[i].Error = status, at, detail
			return
		}
	}
}

func safeError(err error) string {
	if err == nil {
		return ""
	}
	msg := config.RedactValue("sprint.stage_error", err.Error())
	msg = strings.ReplaceAll(msg, "\n", " ")
	msg = strings.ReplaceAll(msg, "\r", " ")
	msg = strings.ReplaceAll(msg, "\x00", "")
	if len(msg) > 180 {
		msg = msg[:180]
	}
	return msg
}

func validateFlowTarget(stage PlanningStage) error {
	if stage != StageRequirements && stage != StageCodeContext && stage != StageSprintIndex && stage != StageTechnicalHandbook && stage != StageAreaReasoning && stage != StageReasoning && stage != StagePlan && stage != StageExecute && stage != StageReview && stage != StageSmoke {
		return fmt.Errorf("unsupported sprint flow target %q; supports requirements, code-context, sprint-index, technical-handbook, area-reasoning, reasoning, plan, execute, review, and smoke", stage)
	}
	return nil
}

